import { registerWebComponents } from '@domg-wc/common';
import { VlButtonComponent } from '@domg-wc/components/atom';
import { VlInfoTile, VlPopoverComponent } from '@domg-wc/components/block';

// VlPopoverComponent registreert zelf vl-popover-action-list en vl-popover-action.
registerWebComponents([VlInfoTile, VlPopoverComponent, VlButtonComponent]);

// Een klik op de tegel volgt het event vl-click-info-tile; het bubbelt en is composed.
document.querySelector('vl-info-tile[clickable]').addEventListener('vl-click-info-tile', () => {
    console.log('info tile aangeklikt');
});
